define([],function(){var serialiseCollage=function(panel){var hidden=panel.querySelector('.ef-collage-data');var snapshot=panel.querySelector('.ef-collage-snapshot');var canvas=panel.querySelector('.ef-collage-canvas');if(!hidden||!canvas){return;}var items=[];canvas.querySelectorAll('.ef-collage-item').forEach(function(item){var file=item.getAttribute('data-file');if(!file){return;}var left=parseFloat(item.style.left)||0;var top=parseFloat(item.style.top)||0;var width=parseFloat(item.style.width)||22;items.push({file:file,x:Math.round(left*10),y:Math.round(top*6),w:Math.round(width*10)});});hidden.value=JSON.stringify(items);if(snapshot){snapshot.value='';}};var bringToFront=function(canvas,item){var max=1;canvas.querySelectorAll('.ef-collage-item').forEach(function(node){max=Math.max(max,parseInt(node.style.zIndex||'1',10));});item.style.zIndex=String(max+1);};var initCollage=function(panel){var canvas=panel.querySelector('.ef-collage-canvas');if(!canvas||panel.classList.contains('ef-collage-readonly')){return;}var remove=panel.querySelector('.ef-collage-remove');var selected=null;var selectItem=function(item){panel.querySelectorAll('.ef-collage-item').forEach(function(node){node.classList.remove('ef-collage-selected');});selected=item;if(selected){selected.classList.add('ef-collage-selected');bringToFront(canvas,selected);serialiseCollage(panel);}};var addItem=function(file,src){var count=canvas.querySelectorAll('.ef-collage-item').length;var item=document.createElement('div');item.className='ef-collage-item ef-collage-selected';item.setAttribute('data-file',file);item.style.left=(8+(count*5)%45)+'%';item.style.top=(8+(count*4)%35)+'%';item.style.width='22%';item.style.zIndex=String(count+1);var newimg=document.createElement('img');newimg.src=src;newimg.alt='';newimg.draggable=false;item.appendChild(newimg);var resizeHandle=document.createElement('span');resizeHandle.className='ef-collage-resize';resizeHandle.setAttribute('aria-hidden','true');item.appendChild(resizeHandle);canvas.appendChild(item);if(newimg){newimg.addEventListener('load',function(){serialiseCollage(panel);});}selectItem(item);serialiseCollage(panel);};panel.querySelectorAll('.ef-collage-choice').forEach(function(button){button.addEventListener('click',function(){addItem(button.getAttribute('data-file'),button.getAttribute('data-src'));});});canvas.querySelectorAll('.ef-collage-item img').forEach(function(img){img.addEventListener('load',function(){serialiseCollage(panel);});});if(remove){remove.addEventListener('click',function(){if(selected){selected.remove();selected=null;serialiseCollage(panel);}});}canvas.addEventListener('mousedown',function(event){var item=event.target.closest('.ef-collage-item');if(!item||!canvas.contains(item)){selectItem(null);return;}event.preventDefault();selectItem(item);var resizing=event.target.classList.contains('ef-collage-resize');var startX=event.clientX;var startY=event.clientY;var startLeft=parseFloat(item.style.left)||0;var startTop=parseFloat(item.style.top)||0;var startWidth=parseFloat(item.style.width)||22;var rect=canvas.getBoundingClientRect();var move=function(moveEvent){if(resizing){var widthPct=startWidth+((moveEvent.clientX-startX)/rect.width*100);widthPct=Math.max(8,Math.min(65,widthPct));item.style.width=widthPct+'%';}else{var leftPct=startLeft+((moveEvent.clientX-startX)/rect.width*100);var topPct=startTop+((moveEvent.clientY-startY)/rect.height*100);item.style.left=Math.max(0,Math.min(96,leftPct))+'%';item.style.top=Math.max(0,Math.min(92,topPct))+'%';}};var up=function(){document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up);serialiseCollage(panel);};document.addEventListener('mousemove',move);document.addEventListener('mouseup',up);});serialiseCollage(panel);};return{init:function(){var bars=document.querySelectorAll('.ef-animate-bars');var hearts=document.querySelectorAll('.ef-animate-hearts');var skills=document.querySelectorAll('.ef-animate-skills');var personalities=document.querySelectorAll('.ef-animate-personality');var collages=document.querySelectorAll('.ef-collage-panel');var animateBars=function(panel){if(panel.getAttribute('data-ef-animated')==='1'){return;}panel.setAttribute('data-ef-animated','1');var fills=panel.querySelectorAll('.ef-sp-fill');fills.forEach(function(fill,index){var width=fill.getAttribute('data-width')||'0';window.setTimeout(function(){fill.style.width=width+'%';},index*330);});};var animateHearts=function(panel){if(panel.getAttribute('data-ef-animated')==='1'){return;}panel.setAttribute('data-ef-animated','1');var items=panel.querySelectorAll('.ef-pf-item');items.forEach(function(item,index){window.setTimeout(function(){item.classList.add('ef-pf-visible');},index*80);});};var animateSkills=function(panel){if(panel.getAttribute('data-ef-animated')==='1'){return;}panel.setAttribute('data-ef-animated','1');var bubbles=panel.querySelectorAll('.ef-sf-bubble');bubbles.forEach(function(bubble,index){window.setTimeout(function(){bubble.classList.add('ef-sf-visible');},index*220);});};var animatePersonality=function(panel){if(panel.getAttribute('data-ef-animated')==='1'){return;}panel.setAttribute('data-ef-animated','1');window.setTimeout(function(){panel.classList.add('ef-pm-visible');},100);};var observeOrRun=function(nodes,callback){if(!nodes.length){return;}if(!('IntersectionObserver'in window)){nodes.forEach(callback);return;}var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){callback(entry.target);observer.unobserve(entry.target);}});},{threshold:0.25});nodes.forEach(function(panel){observer.observe(panel);});};collages.forEach(initCollage);observeOrRun(bars,animateBars);observeOrRun(hearts,animateHearts);observeOrRun(skills,animateSkills);observeOrRun(personalities,animatePersonality);}};});

